window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["training-data-governance"]={"title":"训练数据治理：让模型所学内容可追溯、可审计、可处置","subtitle":"从来源与授权、谱系、过滤去重和配比，到污染、删除请求、训练快照与事故响应。","thesis":"训练数据治理不是训练前清洗一次，而是贯穿获取、授权、处理、配比、训练、评测、响应和退役的控制系统。目标不是声称数据“绝对干净”，而是建立<b>样本—处理—快照—模型—评测</b>的可追溯关系，并在风险出现时知道能做什么、不能证明什么。","quality":{"contractVersion":2,"formulas":[{"id":"training-data-governance-formula-1","section":4,"formulaIndex":1,"symbols":[{"name":"z","meaning":"公式中的“z”是本节计算所使用的量，具体角色由紧邻文字定义。","evidence":"4 去重改变的是有效训练权重 机制 同一段文本出现 20 次"}]},{"id":"training-data-governance-formula-2","section":5,"formulaIndex":1,"symbols":[{"name":"P","meaning":"公式中的“P”是本节计算所使用的量，具体角色由紧邻文字定义。","evidence":"去重与配比怎样重塑一个 100 万样本快照 逐步演算 客服语料只有 10 万条"}]}],"examples":[{"section":5,"evidence":{"setup":"去重与配比怎样重塑一个 100 万样本快照 逐步演算 客服语料只有 10 万条","rule":"却因重复 5 次占到多少训练曝光","steps":"来源 原始条数 去重后 原始混合曝光 治理后目标曝光 通用网页 700k 500k 70% 55% 客服对话 100k×平均5副本 100k 等效约 25%–40% 20% 政策文档 50k 45k 5% 15% 多语言长尾 150k 140k 15% 10% 假设原始拼接总记录 1.4M","interpretation":"其中客服物理副本 500k"}}],"termReviews":[],"sectionContracts":[{"section":1,"definition":{"answer":"本节对“治理对象是生命周期，不是一个文件夹”的界定是：1 治理对象是生命周期","evidence":"1 治理对象是生命周期"},"problem":{"answer":"本节处理的实际问题是：不是一个文件夹 直觉 为什么训练前删过敏感词","evidence":"不是一个文件夹 直觉 为什么训练前删过敏感词"},"inputOutput":{"answer":"本节的输入与输出关系是：部署后仍会遇到版权、隐私和记忆事故","evidence":"部署后仍会遇到版权、隐私和记忆事故"},"mechanism":{"answer":"本节给出的工作机制是：规则、许可和当事人请求也会在训练后变化","evidence":"规则、许可和当事人请求也会在训练后变化"},"interpretation":{"answer":"本节要求这样解释结果：数据会被抓取、解压、规范化、切块、去重、分类、混合和复制成多个快照","evidence":"数据会被抓取、解压、规范化、切块、去重、分类、混合和复制成多个快照"},"boundary":{"answer":"本节明确的适用边界是：模型失败又会产生修复数据与新的评测题","evidence":"模型失败又会产生修复数据与新的评测题"}},{"section":2,"definition":{"answer":"本节对“谱系要从样本连到模型发布”的界定是：2 谱系要从样本连到模型发布 机制 发现一段个人信息被复述时","evidence":"2 谱系要从样本连到模型发布 机制 发现一段个人信息被复述时"},"problem":{"answer":"本节处理的实际问题是：怎样找到所有副本和受影响模型","evidence":"怎样找到所有副本和受影响模型"},"inputOutput":{"answer":"本节的输入与输出关系是：为原始对象保存稳定 source id、获取时间、URI、内容哈希、许可/用途、地域与敏感分类","evidence":"为原始对象保存稳定 source id、获取时间、URI、内容哈希、许可/用途、地域与敏感分类"},"mechanism":{"answer":"本节给出的工作机制是：训练运行反向链接确切清单","evidence":"训练运行反向链接确切清单"},"interpretation":{"answer":"本节要求这样解释结果：每个处理任务保存代码/规则版本、父产物和删除原因","evidence":"每个处理任务保存代码/规则版本、父产物和删除原因"},"boundary":{"answer":"本节明确的适用边界是：数据混合保存来源权重、抽样种子和快照哈希","evidence":"数据混合保存来源权重、抽样种子和快照哈希"}},{"section":3,"definition":{"answer":"本节对“授权、隐私与质量是三个不同判断”的界定是：3 授权、隐私与质量是三个不同判断 治理 公开网页、内容质量高","evidence":"3 授权、隐私与质量是三个不同判断 治理 公开网页、内容质量高"},"problem":{"answer":"本节处理的实际问题是：是否就能安全用于任何训练","evidence":"是否就能安全用于任何训练"},"inputOutput":{"answer":"本节的输入与输出关系是：公开可访问不自动等于获得训练许可","evidence":"公开可访问不自动等于获得训练许可"},"mechanism":{"answer":"本节给出的工作机制是：有许可不表示不含个人敏感信息","evidence":"有许可不表示不含个人敏感信息"},"interpretation":{"answer":"本节要求这样解释结果：合法合规也不表示数据准确或代表目标群体","evidence":"合法合规也不表示数据准确或代表目标群体"},"boundary":{"answer":"本节明确的适用边界是：分别记录来源权利/用途限制、个人数据目的与最小化、内容质量/安全标签","evidence":"分别记录来源权利/用途限制、个人数据目的与最小化、内容质量/安全标签"}},{"section":4,"definition":{"answer":"本节对“去重改变的是有效训练权重”的界定是：4 去重改变的是有效训练权重 机制 同一段文本出现 20 次","evidence":"4 去重改变的是有效训练权重 机制 同一段文本出现 20 次"},"problem":{"answer":"本节处理的实际问题是：若均匀按样本采样","evidence":"若均匀按样本采样"},"inputOutput":{"answer":"本节的输入与输出关系是：一条内容的近似有效概率与副本数成正比","evidence":"一条内容的近似有效概率与副本数成正比"},"mechanism":{"answer":"本节给出的工作机制是：并把评测题镜像泄漏到训练","evidence":"并把评测题镜像泄漏到训练"},"interpretation":{"answer":"本节要求这样解释结果：它会增加逐字记忆、让高重复来源支配梯度","evidence":"它会增加逐字记忆、让高重复来源支配梯度"},"boundary":{"answer":"本节明确的适用边界是：精确哈希只抓完全相同内容","evidence":"精确哈希只抓完全相同内容"}},{"section":5,"definition":{"answer":"本节对“运行示例：去重与配比怎样重塑一个 100 万样本快照”的界定是：去重与配比怎样重塑一个 100 万样本快照 逐步演算 客服语料只有 10 万条","evidence":"去重与配比怎样重塑一个 100 万样本快照 逐步演算 客服语料只有 10 万条"},"problem":{"answer":"本节处理的实际问题是：却因重复 5 次占到多少训练曝光","evidence":"却因重复 5 次占到多少训练曝光"},"inputOutput":{"answer":"本节的输入与输出关系是：来源 原始条数 去重后 原始混合曝光 治理后目标曝光 通用网页 700k 500k 70% 55% 客服对话 100k×平均5副本 100k 等效约 25%–40% 20% 政策文档 50k 45k 5% 15% 多语言长尾 150k 140k 15% 10% 假设原始拼接总记录 1.4M","evidence":"来源 原始条数 去重后 原始混合曝光 治理后目标曝光 通用网页 700k 500k 70% 55% 客服对话 100k×平均5副本 100k 等效约 25%–40% 20% 政策文档 50k 45k 5% 15% 多语言长尾 150k 140k 15% 10% 假设原始拼接总记录 1.4M"},"mechanism":{"answer":"本节给出的工作机制是：它的均匀采样曝光约 35.7%","evidence":"它的均匀采样曝光约 35.7%"},"interpretation":{"answer":"本节要求这样解释结果：其中客服物理副本 500k","evidence":"其中客服物理副本 500k"},"boundary":{"answer":"本节明确的适用边界是：而语义内容只有 100k","evidence":"而语义内容只有 100k"}},{"section":6,"definition":{"answer":"本节对“过滤器也会系统性偏向某些数据”的界定是：6 过滤器也会系统性偏向某些数据 失败边界 “高质量分类器”保留 90% 英文、只保留 45% 某低资源语言","evidence":"6 过滤器也会系统性偏向某些数据 失败边界 “高质量分类器”保留 90% 英文、只保留 45% 某低资源语言"},"problem":{"answer":"本节处理的实际问题是：质量分类器常把主流百科文风当标准","evidence":"质量分类器常把主流百科文风当标准"},"inputOutput":{"answer":"本节的输入与输出关系是：把口语、方言、残障表达、代码混排或低资源语言误判为垃圾","evidence":"把口语、方言、残障表达、代码混排或低资源语言误判为垃圾"},"mechanism":{"answer":"本节给出的工作机制是：毒性过滤也可能过删讨论被歧视群体的文本","evidence":"毒性过滤也可能过删讨论被歧视群体的文本"},"interpretation":{"answer":"本节要求这样解释结果：总体保留率会掩盖这种分布重塑","evidence":"总体保留率会掩盖这种分布重塑"},"boundary":{"answer":"本节明确的适用边界是：对每条规则保存原因码和分数","evidence":"对每条规则保存原因码和分数"}},{"section":7,"definition":{"answer":"本节对“污染、投毒和合成回流的因果不同”的界定是：7 污染、投毒和合成回流的因果不同 风险 测试题泄漏、攻击者注入后门、模型输出再训练","evidence":"7 污染、投毒和合成回流的因果不同 风险 测试题泄漏、攻击者注入后门、模型输出再训练"},"problem":{"answer":"本节处理的实际问题是：为什么不能用同一过滤器解决","evidence":"为什么不能用同一过滤器解决"},"inputOutput":{"answer":"本节的输入与输出关系是：风险 目标/机制 观测 防线 评测污染 题或答案进入训练 异常相似、时间矛盾 隔离保留集、近邻扫描 数据投毒 恶意改变行为/后门 来源异常、触发器、簇突增 信誉、签名、配额、红队 合成回流 生成分布替代真实尾部 措辞同质、来源不明 合成标记、真实锚点、配比 来源漂移 站点内容/许可随时间变 版本与分布变化 定期复核、快照许可 异常数据不能自动进入重训","evidence":"风险 目标/机制 观测 防线 评测污染 题或答案进入训练 异常相似、时间矛盾 隔离保留集、近邻扫描 数据投毒 恶意改变行为/后门 来源异常、触发器、簇突增 信誉、签名、配额、红队 合成回流 生成分布替代真实尾部 措辞同质、来源不明 合成标记、真实锚点、配比 来源漂移 站点内容/许可随时间变 版本与分布变化 定期复核、快照许可 异常数据不能自动进入重训"},"mechanism":{"answer":"本节给出的工作机制是：避免攻击者通过反馈渠道投毒","evidence":"避免攻击者通过反馈渠道投毒"},"interpretation":{"answer":"本节要求这样解释结果：生产失败回流要脱敏、去重、确认标签与来源","evidence":"生产失败回流要脱敏、去重、确认标签与来源"},"boundary":{"answer":"本节明确的适用边界是：7 污染、投毒和合成回流的因果不同","evidence":"7 污染、投毒和合成回流的因果不同"}},{"section":8,"definition":{"answer":"本节对“删除文件不等于模型已经遗忘”的界定是：8 删除文件不等于模型已经遗忘 处置 收到删除请求后","evidence":"8 删除文件不等于模型已经遗忘 处置 收到删除请求后"},"problem":{"answer":"本节处理的实际问题是：哪些结果能可靠承诺","evidence":"哪些结果能可靠承诺"},"inputOutput":{"answer":"本节的输入与输出关系是：已经训练的权重是大量样本共同优化结果","evidence":"已经训练的权重是大量样本共同优化结果"},"mechanism":{"answer":"本节给出的工作机制是：可以从原始存储、派生数据集、缓存和未来训练清单删除已定位对象","evidence":"可以从原始存储、派生数据集、缓存和未来训练清单删除已定位对象"},"interpretation":{"answer":"本节要求这样解释结果：并用谱系阻止再次摄取","evidence":"并用谱系阻止再次摄取"},"boundary":{"answer":"本节明确的适用边界是：删除文件不会逆转参数更新","evidence":"删除文件不会逆转参数更新"}},{"section":9,"definition":{"answer":"本节对“治理控制要落到发布门禁和事故演练”的界定是：9 治理控制要落到发布门禁和事故演练 工程 有 datasheet 和清单","evidence":"9 治理控制要落到发布门禁和事故演练 工程 有 datasheet 和清单"},"problem":{"answer":"本节处理的实际问题是：为什么仍可能在下一次训练重复犯错","evidence":"为什么仍可能在下一次训练重复犯错"},"inputOutput":{"answer":"本节的输入与输出关系是：将治理变成自动门禁","evidence":"将治理变成自动门禁"},"mechanism":{"answer":"本节给出的工作机制是：训练前输出数据卡","evidence":"训练前输出数据卡"},"interpretation":{"answer":"本节要求这样解释结果：未知来源、缺许可、敏感等级不明、评测近邻、异常重复率或混合权重超界时阻断快照","evidence":"未知来源、缺许可、敏感等级不明、评测近邻、异常重复率或混合权重超界时阻断快照"},"boundary":{"answer":"本节明确的适用边界是：人工豁免必须有期限和责任人","evidence":"人工豁免必须有期限和责任人"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>设计数据谱系和版本清单；推导重复与配比的有效权重；区分许可、隐私、污染和投毒；处理删除请求与模型影响验证。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>治理对象是生命周期，不是一个文件夹<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">为什么训练前删过敏感词，部署后仍会遇到版权、隐私和记忆事故？</p><p>数据会被抓取、解压、规范化、切块、去重、分类、混合和复制成多个快照；规则、许可和当事人请求也会在训练后变化。模型失败又会产生修复数据与新的评测题。因此每次转换都需要版本、责任人、输入与产物关系。</p><p>治理回答四件事：数据为何能用；经历了什么处理；进入了哪些模型；发现问题后能定位和处置到什么程度。只保存最终 parquet 不能回答这些问题。</p><div class=\"dd-note\"><b>证据链：</b>来源记录证明“从哪里来”，授权记录说明“为何可用”，处理谱系说明“怎样改变”，训练清单说明“影响了哪些模型”。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>谱系要从样本连到模型发布<span class=\"dd-badge eng\">机制</span></h2><p class=\"dd-lead\">发现一段个人信息被复述时，怎样找到所有副本和受影响模型？</p><p>为原始对象保存稳定 source id、获取时间、URI、内容哈希、许可/用途、地域与敏感分类；每个处理任务保存代码/规则版本、父产物和删除原因；数据混合保存来源权重、抽样种子和快照哈希；训练运行反向链接确切清单。</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 710 255\" role=\"img\" aria-label=\"训练数据从来源、处理、混合到模型和事故响应的谱系图\"><defs><marker id=\"tg1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#6b7484\"/></marker></defs><rect x=\"18\" y=\"76\" width=\"116\" height=\"70\" rx=\"8\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"76\" y=\"101\" text-anchor=\"middle\" class=\"svg-t\">来源 S17</text><text x=\"76\" y=\"122\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">URI/许可/哈希</text><path d=\"M134,111 L174,111\" stroke=\"#6b7484\" marker-end=\"url(#tg1)\"/><rect x=\"176\" y=\"76\" width=\"116\" height=\"70\" rx=\"8\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"234\" y=\"101\" text-anchor=\"middle\" class=\"svg-t\">处理 P9</text><text x=\"234\" y=\"122\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">脱敏/去重/过滤</text><path d=\"M292,111 L332,111\" stroke=\"#6b7484\" marker-end=\"url(#tg1)\"/><rect x=\"334\" y=\"76\" width=\"116\" height=\"70\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"392\" y=\"101\" text-anchor=\"middle\" class=\"svg-t\">快照 D42</text><text x=\"392\" y=\"122\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">清单/配比/种子</text><path d=\"M450,111 L490,111\" stroke=\"#6b7484\" marker-end=\"url(#tg1)\"/><rect x=\"492\" y=\"76\" width=\"116\" height=\"70\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"550\" y=\"101\" text-anchor=\"middle\" class=\"svg-t\">模型 M8</text><text x=\"550\" y=\"122\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">训练运行/权重</text><path d=\"M608,111 L680,111\" stroke=\"#6b7484\" marker-end=\"url(#tg1)\"/><text x=\"645\" y=\"91\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">部署</text><path d=\"M550,147 C546,215 235,220 234,148\" fill=\"none\" stroke=\"#c77b72\" stroke-dasharray=\"5 4\" marker-end=\"url(#tg1)\"/><text x=\"392\" y=\"208\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">事故/删除请求：反查快照与模型，更新规则、数据和回归评测</text></svg><figcaption>图 1　谱系必须双向可查：从模型回到数据，也能从问题样本找到所有受影响产物。</figcaption></figure></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>授权、隐私与质量是三个不同判断<span class=\"dd-badge eng\">治理</span></h2><p class=\"dd-lead\">公开网页、内容质量高，是否就能安全用于任何训练？</p><p>公开可访问不自动等于获得训练许可；有许可不表示不含个人敏感信息；合法合规也不表示数据准确或代表目标群体。分别记录来源权利/用途限制、个人数据目的与最小化、内容质量/安全标签，避免用一个“approved=true”掩盖不同责任。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>轴</th><th>核心问题</th><th>证据</th><th>处置</th></tr></thead><tbody><tr><td>授权/许可</td><td>能否按此目的使用</td><td>合同、许可、来源条款</td><td>排除或限制用途</td></tr><tr><td>隐私</td><td>是否必要、可识别、可删除</td><td>目的、同意/依据、分类</td><td>最小化、脱敏、访问控制</td></tr><tr><td>质量</td><td>是否准确、代表、非垃圾</td><td>抽样审计与分布</td><td>过滤、降权、补充</td></tr><tr><td>安全</td><td>是否投毒、恶意或含秘密</td><td>信誉、异常与扫描</td><td>隔离、人工复核</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>去重改变的是有效训练权重<span class=\"dd-badge math\">机制</span></h2><p class=\"dd-lead\">同一段文本出现 20 次，除了浪费计算，还改变了什么？</p><p>若均匀按样本采样，一条内容的近似有效概率与副本数成正比。它会增加逐字记忆、让高重复来源支配梯度，并把评测题镜像泄漏到训练。精确哈希只抓完全相同内容；MinHash/局部敏感哈希抓词面近邻，语义去重抓改写，但误删风险依次上升。</p><div class=\"dd-formula\" data-formula-id=\"training-data-governance-formula-1\" data-display=\"mathml\"><math display=\"block\" aria-label=\"内容 z 的有效权重 w(z) ∝ Σⱼ 1[样本 j 属于 z 的重复簇] · 采样权重ⱼ\"><mrow><mtext>内容</mtext><mspace width=\"0.35em\"/><mi>z</mi><mspace width=\"0.35em\"/><mtext>的有效权重</mtext><mspace width=\"0.35em\"/><mi>w</mi><mo>(</mo><mi>z</mi><mo>)</mo><mspace width=\"0.35em\"/><mo>∝</mo><mspace width=\"0.35em\"/><mi>Σ</mi><mo>ⱼ</mo><mspace width=\"0.35em\"/><mn>1</mn><mo>[</mo><mtext>样本</mtext><mspace width=\"0.35em\"/><mi>j</mi><mspace width=\"0.35em\"/><mtext>属于</mtext><mspace width=\"0.35em\"/><mi>z</mi><mspace width=\"0.35em\"/><mtext>的重复簇</mtext><mo>]</mo><mspace width=\"0.35em\"/><mo>·</mo><mspace width=\"0.35em\"/><mtext>采样权重</mtext><mo>ⱼ</mo></mrow></math></div><p>近似去重应在文档、段落和跨数据集层面运行，并按语言、来源、格式和群体报告保留率。模板化代码、法律条款和稀有语言可能天然相似，盲目追求最低重复率会删掉有效结构。</p><div class=\"dd-note warn\"><b>测试集先隔离。</b>　应在训练混合前用精确与语义近邻检查评测题及衍生讲解；训练后再检测只能发现风险，不能恢复独立性。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>运行示例：去重与配比怎样重塑一个 100 万样本快照<span class=\"dd-badge math\">逐步演算</span></h2><p class=\"dd-lead\">客服语料只有 10 万条，却因重复 5 次占到多少训练曝光？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>来源</th><th>原始条数</th><th>去重后</th><th>原始混合曝光</th><th>治理后目标曝光</th></tr></thead><tbody><tr><td>通用网页</td><td>700k</td><td>500k</td><td>70%</td><td>55%</td></tr><tr><td>客服对话</td><td>100k×平均5副本</td><td>100k</td><td>等效约 25%–40%</td><td>20%</td></tr><tr><td>政策文档</td><td>50k</td><td>45k</td><td>5%</td><td>15%</td></tr><tr><td>多语言长尾</td><td>150k</td><td>140k</td><td>15%</td><td>10%</td></tr></tbody></table></div><p>假设原始拼接总记录 1.4M，其中客服物理副本 500k，它的均匀采样曝光约 35.7%，而语义内容只有 100k。去重后总独特约 785k，客服自然比例约 12.7%。团队若根据任务将其显式设为 20%，这是可审计配比决策，不再由抓取重复偶然决定。</p><div class=\"dd-formula\" data-formula-id=\"training-data-governance-formula-2\" data-display=\"mathml\"><math display=\"block\" aria-label=\"P训练(x)=Σᵢ pᵢPᵢ(x)，Σpᵢ=1；100k 步下政策目标曝光 15%≈15k 步\"><mrow><mi>P</mi><mtext>训练</mtext><mo>(</mo><mi>x</mi><mo>)=Σ</mo><mo>ᵢ</mo><mspace width=\"0.35em\"/><mi>p</mi><mo>ᵢ</mo><mi>P</mi><mo>ᵢ</mo><mo>(</mo><mi>x</mi><mo>)</mo><mtext>，</mtext><mi>Σ</mi><mi>p</mi><mo>ᵢ</mo><mo>=</mo><mn>1</mn><mtext>；</mtext><mn>100</mn><mi>k</mi><mspace width=\"0.35em\"/><mtext>步下政策目标曝光</mtext><mspace width=\"0.35em\"/><mn>15</mn><mo>%≈</mo><mn>15</mn><mi>k</mi><mspace width=\"0.35em\"/><mtext>步</mtext></mrow></math></div><p>配比提高政策能力也可能损害通用、多语言或旧知识保持。必须在能力、安全、公平和记忆切片做消融，不能只看退款准确率。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>过滤器也会系统性偏向某些数据<span class=\"dd-badge eng\">失败边界</span></h2><p class=\"dd-lead\">“高质量分类器”保留 90% 英文、只保留 45% 某低资源语言，意味着什么？</p><p>质量分类器常把主流百科文风当标准，把口语、方言、残障表达、代码混排或低资源语言误判为垃圾。毒性过滤也可能过删讨论被歧视群体的文本。总体保留率会掩盖这种分布重塑。</p><p>对每条规则保存原因码和分数；在来源/语言/群体切片抽样双标，测精确率、召回率和保留差异；对高不确定样本隔离人工复核。过滤前后都保存统计摘要，原始敏感内容则受限访问并按保留政策处理。</p><div class=\"dd-note warn\"><b>过滤不是中立清洁。</b>　它定义了模型可见世界的一部分，是能力和价值决策，应接受评测与治理审批。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>污染、投毒和合成回流的因果不同<span class=\"dd-badge eng\">风险</span></h2><p class=\"dd-lead\">测试题泄漏、攻击者注入后门、模型输出再训练，为什么不能用同一过滤器解决？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>风险</th><th>目标/机制</th><th>观测</th><th>防线</th></tr></thead><tbody><tr><td>评测污染</td><td>题或答案进入训练</td><td>异常相似、时间矛盾</td><td>隔离保留集、近邻扫描</td></tr><tr><td>数据投毒</td><td>恶意改变行为/后门</td><td>来源异常、触发器、簇突增</td><td>信誉、签名、配额、红队</td></tr><tr><td>合成回流</td><td>生成分布替代真实尾部</td><td>措辞同质、来源不明</td><td>合成标记、真实锚点、配比</td></tr><tr><td>来源漂移</td><td>站点内容/许可随时间变</td><td>版本与分布变化</td><td>定期复核、快照许可</td></tr></tbody></table></div><p>异常数据不能自动进入重训。生产失败回流要脱敏、去重、确认标签与来源，避免攻击者通过反馈渠道投毒。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>删除文件不等于模型已经遗忘<span class=\"dd-badge eng\">处置</span></h2><p class=\"dd-lead\">收到删除请求后，哪些结果能可靠承诺，哪些不能？</p><p>可以从原始存储、派生数据集、缓存和未来训练清单删除已定位对象，并用谱系阻止再次摄取。已经训练的权重是大量样本共同优化结果，删除文件不会逆转参数更新；输出拦截也只降低暴露，不证明内部影响消失。</p><ol class=\"dd-steps\"><li>验证请求主体、范围和法律/合同依据。</li><li>用精确/近似标识找到副本与派生产物。</li><li>更新删除清单、过滤器和未来快照。</li><li>反查受影响训练运行与部署模型。</li><li>按风险选择重训、机器遗忘、检索/输出控制或退役。</li><li>用成员推断、诱导复现和任务回归验证，但如实说明证据边界。</li></ol><p>机器遗忘本身需证明效用损失和残余记忆；不能把运行一个脚本等同于合规完成。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>治理控制要落到发布门禁和事故演练<span class=\"dd-badge intuition\">工程</span></h2><p class=\"dd-lead\">有 datasheet 和清单，为什么仍可能在下一次训练重复犯错？</p><p>将治理变成自动门禁：未知来源、缺许可、敏感等级不明、评测近邻、异常重复率或混合权重超界时阻断快照；人工豁免必须有期限和责任人。训练前输出数据卡，训练后运行记忆、偏差、安全和能力消融。</p><p>演练“发现某来源撤销授权”：能否在小时内列出快照、训练运行、模型、部署和下游衍生数据；能否构建不含来源的新快照并估算重训/替代成本。无法执行的谱系只是文档装饰。</p><div class=\"dd-note warn\"><b>治理不是绝对保证。</b>　来源元数据可能错误、近似匹配会漏、模型影响难以逐样本归因；报告残余风险和证据强度。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与概念依赖<span class=\"dd-badge intuition\">常见误区与学习路线</span></h2><p class=\"dd-lead\">可靠治理不声称数据无瑕，而是让关键决策与问题处置有证据可循。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>公开可访问即可任意训练</td><td>访问、许可、隐私与用途是不同问题</td></tr><tr><td>去重越彻底越好</td><td>语义误删会伤害稀有语言和真实模板</td></tr><tr><td>过滤器只提高质量</td><td>它也重塑群体、语言和价值分布</td></tr><tr><td>删源文件即模型遗忘</td><td>既有参数影响需模型级处置与验证</td></tr><tr><td>生产反馈可自动训练</td><td>需防错标、隐私、选择偏差和投毒</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸学习</th></tr></thead><tbody><tr><td>先修</td><td>预训练、数据工程、概率采样与评测</td></tr><tr><td><b>本页核心</b></td><td>授权、谱系、去重、配比、删除与快照门禁</td></tr><tr><td>数据方法</td><td>合成数据、自监督学习、数据投毒</td></tr><tr><td>生命周期</td><td>隐私、偏见公平、模型评测、漂移监控与治理</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">11</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>登记来源/授权/敏感等级</li><li>版本化处理与去重原因</li><li>显式设计混合配比并隔离评测</li><li>冻结清单连接训练运行与模型</li><li>训练后评测记忆/偏差/能力</li><li>事故或请求沿谱系处置并更新门禁</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">12</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>谱系为何要双向可查？</li><li>重复为什么改变模型而不只是磁盘？</li><li>示例中客服去重后自然比例约多少？</li><li>删除文件为何不等于遗忘？</li><li>生产失败为何不能自动回流？</li><li>假设“训练数据治理：让模型所学内容可追溯、可审计、可处置”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“训练数据治理：让模型所学内容可追溯、可审计、可处置”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>既要从模型复现确切数据，也要从问题样本找出所有受影响快照和模型。</li><li>副本提高有效采样权重、记忆和污染风险。</li><li>100k/785k≈12.7%，显式设为 20% 是另一个配比决策。</li><li>训练更新已分布在权重中，需重训/遗忘/控制及模型级验证。</li><li>可能含错标、选择偏差、个人数据与攻击者投毒。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/1803.09010\" target=\"_blank\" rel=\"noopener\">Datasheets for Datasets</a>：数据集文档与生命周期问责</li><li><a href=\"https://aclanthology.org/Q18-1041/\" target=\"_blank\" rel=\"noopener\">Data Statements for NLP</a>：语言数据群体与语境记录</li><li><a href=\"https://arxiv.org/abs/2107.06499\" target=\"_blank\" rel=\"noopener\">Deduplicating Training Data Makes Language Models Better</a>：重复、记忆与评测污染</li><li><a href=\"https://arxiv.org/abs/2101.00027\" target=\"_blank\" rel=\"noopener\">The Pile</a>：大规模训练语料来源与构成</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
